def _attach_filter_once(
    logger: logging.Logger, filter_instance: logging.Filter
) -> None:
    """Attach a filter only if an instance of the same type is not already present."""
    if any(
        isinstance(existing_filter, type(filter_instance))
        for existing_filter in logger.filters
    ):
        return
    logger.addFilter(filter_instance)


